package com.campusnova.knowledge; import java.util.*;
public class RetrievalResult { private final List<KnowledgeDocument> documents; private final double confidence; public RetrievalResult(List<KnowledgeDocument> d,double c){documents=d;confidence=c;} public List<KnowledgeDocument> getDocuments(){return documents;} public double getConfidence(){return confidence;} public boolean hasContext(){return !documents.isEmpty();} public List<String> sources(){List<String>s=new ArrayList<String>();for(KnowledgeDocument d:documents){String label=d.getSourceUrl()==null?d.getSource():d.getSource()+" — "+d.getSourceUrl().replaceFirst("#.*$","");if(!s.contains(label))s.add(label);}return s;} }
